def choose_move(observation):
    # Defensive extraction of necessary observation fields
    me = observation.get('me', {})
    position = me.get('position', [0, 0])
    grid = observation.get('grid', {})
    resource_positions = observation.get('resources', [])
    opponents = observation.get('opponents', [])

    # Helper function to compute Manhattan distance
    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Determine move in resource collection mode
    def resource_collection_move():
        # Find closest resource
        min_dist = float('inf')
        target = None
        for res in resource_positions:
            if res is not None:
                d = dist(position, res)
                if d < min_dist:
                    min_dist = d
                    target = res
        # Move towards resource if exists
        if target:
            dx = dy = 0
            if position[0] < target[0]:
                dx = 1
            elif position[0] > target[0]:
                dx = -1
            elif position[1] < target[1]:
                dy = 1
            elif position[1] > target[1]:
                dy = -1
            return [dx, dy]
        # No resources, stay
        return [0, 0]

    # Determine move in pursuit_evasion mode
    def pursuit_evasion_move():
        # Find closest opponent
        min_dist = float('inf')
        target_pos = None
        for opp in opponents:
            opp_pos = opp.get('position')
            if opp_pos is not None:
                d = dist(position, opp_pos)
                if d < min_dist:
                    min_dist = d
                    target_pos = opp_pos
        if target_pos:
            dx = dy = 0
            if position[0] < target_pos[0]:
                dx = 1
            elif position[0] > target_pos[0]:
                dx = -1
            if position[1] < target_pos[1]:
                dy = 1
            elif position[1] > target_pos[1]:
                dy = -1
            return [dx, dy]
        return [0, 0]

    # Determine move in territory_control mode
    def territory_control_move():
        # Try to move into unclaimed areas
        # Check adjacent cells
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            new_x = position[0] + dx
            new_y = position[1] + dy
            cell = grid.get(str(new_x) + ',' + str(new_y))
            if cell is not None and cell == 'unclaimed':
                return [dx, dy]
        # Otherwise, move randomly
        return [0, 1]

    # Determine game mode
    game_type = observation.get('game_type', '')
    if game_type == 'resource_collection':
        return resource_collection_move()
    elif game_type == 'pursuit_evasion':
        return pursuit_evasion_move()
    elif game_type == 'territory_control':
        return territory_control_move()
    else:
        # Default fallback
        return [0, 0]
